<?php $editando = is_array($editar ?? null); ?>
<section class="page-head"><div><span class="badge">Cadastro</span><h1>Categorias</h1><p>Crie e organize as categorias utilizadas pelos produtos.</p></div><a class="button secondary" href="?route=/dashboard">Voltar ao painel</a></section>
<?php if (!empty($flash)): ?><div class="alert <?= ($flash['tipo'] ?? '') === 'sucesso' ? 'success' : 'error' ?>"><?= htmlspecialchars((string) ($flash['mensagem'] ?? ''), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<section class="crud-layout"><article class="card form-card"><h2><?= $editando ? 'Editar categoria' : 'Nova categoria' ?></h2><form method="post" action="?route=/categorias/salvar"><input type="hidden" name="id" value="<?= (int) ($editar['id'] ?? 0) ?>"><label for="nome">Nome</label><input id="nome" name="nome" maxlength="100" required value="<?= htmlspecialchars((string) ($editar['nome'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><div class="form-actions"><button class="button" type="submit"><?= $editando ? 'Salvar alterações' : 'Cadastrar categoria' ?></button><?php if ($editando): ?><a class="button ghost" href="?route=/categorias">Cancelar</a><?php endif; ?></div></form></article>
<article class="card list-card"><div class="list-title"><h2>Categorias cadastradas</h2><span><?= count($categorias) ?> registro(s)</span></div><?php if (!$categorias): ?><p class="empty-state">Nenhuma categoria cadastrada.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($categorias as $categoria): ?><tr><td><strong><?= htmlspecialchars($categoria['nome'], ENT_QUOTES, 'UTF-8') ?></strong></td><td><span class="pill <?= $categoria['ativo'] ? 'active' : 'inactive' ?>"><?= $categoria['ativo'] ? 'Ativa' : 'Inativa' ?></span></td><td class="actions-cell"><a class="text-link" href="?route=/categorias&id=<?= (int) $categoria['id'] ?>">Editar</a><form method="post" action="?route=/categorias/status"><input type="hidden" name="id" value="<?= (int) $categoria['id'] ?>"><input type="hidden" name="ativo" value="<?= $categoria['ativo'] ? 0 : 1 ?>"><button class="link-button <?= $categoria['ativo'] ? 'danger-text' : '' ?>" type="submit"><?= $categoria['ativo'] ? 'Desativar' : 'Ativar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article></section>
